:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a3c;
  --text: #f0f0f5;
  --accent: #ff6b6b;
  --accent-hover: #ff8e8e;
  --tile-empty: #3a3a4e;
  --tile-0: #4ecdc4;
  --tile-1: #ffe66d;
  --tile-2: #ff6b6b;
  --tile-3: #a06cd5;
  --focus: #ffffff;
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.game-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.subtitle {
  font-size: 1rem;
  color: #b0b0c0;
  margin-top: 4px;
}

.stats {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.125rem;
}

.stat-label {
  color: #b0b0c0;
}

.stat-value {
  font-weight: 700;
  color: var(--accent);
}

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  aspect-ratio: 1 / 1;
  width: 100%;
}

.tile {
  border-radius: 8px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform 0.1s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  position: relative;
  min-width: 0;
  min-height: 0;
  padding: 0;
  font-size: 0;
  line-height: 0;
}

.tile:hover {
  transform: scale(1.04);
  box-shadow: 0 0 0 2px var(--focus);
}

.tile:focus-visible {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px var(--focus);
  transform: scale(1.04);
}

.tile.selected {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px var(--focus);
  transform: scale(1.06);
}

.tile[data-color="0"] { background: var(--tile-0); }
.tile[data-color="1"] { background: var(--tile-1); }
.tile[data-color="2"] { background: var(--tile-2); }
.tile[data-color="3"] { background: var(--tile-3); }

.solved-message {
  text-align: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  padding: 8px;
  background: rgba(255, 107, 107, 0.15);
  border-radius: 8px;
}

.controls {
  display: flex;
  justify-content: center;
}

.btn {
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: 600;
  color: #1e1e2f;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  padding: 12px 32px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--focus);
}

.btn:active {
  transform: scale(0.97);
  background: #e05555;
}

.instructions {
  font-size: 0.9375rem;
  color: #b0b0c0;
  text-align: center;
  line-height: 1.5;
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
    gap: 16px;
  }
  .game-header h1 {
    font-size: 1.5rem;
  }
  .grid {
    gap: 6px;
  }
  .btn {
    padding: 10px 24px;
  }
}

(function () {
  'use strict';

  const COLORS = 4;
  const SIZE = 4;
  const TOTAL = SIZE * SIZE;

  const gridEl = document.getElementById('grid');
  const swapCountEl = document.getElementById('swap-count');
  const solvedMsgEl = document.getElementById('solved-message');
  const shuffleBtn = document.getElementById('shuffle-btn');

  let board = [];
  let selectedIndex = -1;
  let swapCount = 0;
  let solved = false;

  function createBoard() {
    const arr = [];
    for (let i = 0; i < TOTAL; i++) {
      arr.push(Math.floor(i / SIZE));
    }
    return arr;
  }

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function isSolved() {
    for (let r = 0; r < SIZE; r++) {
      const color = board[r * SIZE];
      for (let c = 1; c < SIZE; c++) {
        if (board[r * SIZE + c] !== color) return false;
      }
    }
    return true;
  }

  function isAdjacent(a, b) {
    if (a < 0 || b < 0) return false;
    const ra = Math.floor(a / SIZE), ca = a % SIZE;
    const rb = Math.floor(b / SIZE), cb = b % SIZE;
    return Math.abs(ra - rb) + Math.abs(ca - cb) === 1;
  }

  function swapTiles(a, b) {
    [board[a], board[b]] = [board[b], board[a]];
  }

  function render() {
    gridEl.innerHTML = '';
    for (let i = 0; i < TOTAL; i++) {
      const tile = document.createElement('button');
      tile.className = 'tile';
      tile.dataset.color = board[i];
      tile.dataset.index = i;
      tile.setAttribute('role', 'gridcell');
      tile.setAttribute('aria-label', `Tile ${i + 1}, color ${board[i] + 1}`);
      tile.tabIndex = i === 0 ? 0 : -1;
      if (i === selectedIndex) tile.classList.add('selected');
      tile.addEventListener('click', onTileClick);
      tile.addEventListener('keydown', onTileKeyDown);
      gridEl.appendChild(tile);
    }
    swapCountEl.textContent = swapCount;
    solvedMsgEl.hidden = !solved;
  }

  function onTileClick(e) {
    const idx = parseInt(e.currentTarget.dataset.index, 10);
    handleSelection(idx);
  }

  function onTileKeyDown(e) {
    const idx = parseInt(e.currentTarget.dataset.index, 10);
    const row = Math.floor(idx / SIZE);
    const col = idx % SIZE;
    let target = -1;

    switch (e.key) {
      case 'ArrowUp':    if (row > 0) target = idx - SIZE; break;
      case 'ArrowDown':  if (row < SIZE - 1) target = idx + SIZE; break;
      case 'ArrowLeft':  if (col > 0) target = idx - 1; break;
      case 'ArrowRight': if (col < SIZE - 1) target = idx + 1; break;
      case 'Enter':
      case ' ':          e.preventDefault(); handleSelection(idx); return;
      case 'Escape':     selectedIndex = -1; render(); focusTile(idx); return;
      default: return;
    }

    if (target >= 0) {
      e.preventDefault();
      focusTile(target);
    }
  }

  function focusTile(idx) {
    const tiles = gridEl.querySelectorAll('.tile');
    tiles.forEach((t, i) => { t.tabIndex = i === idx ? 0 : -1; });
    if (tiles[idx]) tiles[idx].focus();
  }

  function handleSelection(idx) {
    if (solved) return;

    if (selectedIndex === -1) {
      selectedIndex = idx;
      render();
      focusTile(idx);
      return;
    }

    if (selectedIndex === idx) {
      selectedIndex = -1;
      render();
      focusTile(idx);
      return;
    }

    if (isAdjacent(selectedIndex, idx)) {
      swapTiles(selectedIndex, idx);
      swapCount++;
      selectedIndex = -1;
      solved = isSolved();
      render();
      focusTile(idx);
    } else {
      selectedIndex = idx;
      render();
      focusTile(idx);
    }
  }

  function newGame() {
    board = shuffle(createBoard());
    selectedIndex = -1;
    swapCount = 0;
    solved = false;
    render();
    focusTile(0);
  }

  shuffleBtn.addEventListener('click', newGame);

  newGame();
})();
